export function relativeName(value){
  ensure(typeof value==='string'&&value.length<=1000&&value!==''&&!value.includes('\\')&&!value.includes('\0')&&
    !value.startsWith('/')&&value.split('/').every(x=>x&&x!=='.'&&x!=='..'),'FILE_PATH','Select a relative member name.');
  return value;
