  same(manifest.files.filter(x=>x.role==='application').map(({name,bytes,sha256})=>({name:name.slice('application/'.length),bytes,sha256})),
    manifest.application.slice().sort((a,b)=>a.name<b.name?-1:a.name>b.name?1:0));
